WITH filtered_samples AS ( SELECT sd.sample_unique_id, sd.patient_unique_id FROM sample_derived sd WHERE sd.sample_unique_id IN (
) ), profile_level AS ( SELECT COALESCE(MAX(gad.patient_level), 0) AS is_patient_level FROM generic_assay_data_derived gad INNER JOIN filtered_samples fs ON fs.sample_unique_id = gad.sample_unique_id WHERE gad.profile_type = #{profileType} ), entities AS (
SELECT #{stableId} AS stable_id
SELECT DISTINCT gad.entity_stable_id AS stable_id FROM generic_assay_data_derived gad INNER JOIN filtered_samples fs ON fs.sample_unique_id = gad.sample_unique_id WHERE gad.profile_type = #{profileType}
), non_na AS ( SELECT gad.entity_stable_id AS stableId,
AS value, CAST( CASE WHEN (SELECT is_patient_level FROM profile_level) = 1 THEN COUNT(DISTINCT gad.patient_unique_id) ELSE COUNT(DISTINCT gad.sample_unique_id) END AS INTEGER ) AS count FROM generic_assay_data_derived gad INNER JOIN filtered_samples fs ON fs.sample_unique_id = gad.sample_unique_id WHERE gad.profile_type = #{profileType} AND NOT (
)
AND gad.entity_stable_id IN
#{stableId}
GROUP BY gad.entity_stable_id, gad.value ), non_na_totals AS ( SELECT stableId, SUM(count) AS count FROM non_na GROUP BY stableId ), cohort_total AS ( SELECT CAST( CASE WHEN (SELECT is_patient_level FROM profile_level) = 1 THEN COUNT(DISTINCT patient_unique_id) ELSE COUNT(DISTINCT sample_unique_id) END AS INTEGER ) AS count FROM filtered_samples ) SELECT stableId, value, count FROM non_na UNION ALL SELECT entities.stable_id AS stableId, 'NA' AS value, CAST(cohort_total.count - COALESCE(non_na_totals.count, 0) AS INTEGER) AS count FROM entities CROSS JOIN cohort_total LEFT JOIN non_na_totals ON non_na_totals.stableId = entities.stable_id
WHERE cohort_total.count - COALESCE(non_na_totals.count, 0) > 0
ORDER BY stableId, value

